'use strict'

import resource from '../../resource'
import { Enemy, randomInt, drawImage, isInside } from './common'

// A flying flower: it flies over everything, turning little by little, then slows down and lands
// for a while. The sword only hurts it on the ground
const PEAHAT = { life: 2, contactDamage: 0.5 }
const MAX_SPEED = 2
const ACCELERATION = 0.05
const TURN = 0.08
const MIN_FLIGHT_STEPS = 180
const MAX_FLIGHT_STEPS = 420
const LANDED_STEPS = 90
// The blades spin faster when it flies faster
const SPIN_SPEED_STEPS = 8

const STATE_FLYING = 'flying'
const STATE_LANDING = 'landing'
const STATE_LANDED = 'landed'

class Peahat extends Enemy {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, PEAHAT, random)
    this.angle = random() * 2 * Math.PI
    this.speed = 0
    this.flight = 0
    this.spin = 0
    // Exact position: it moves by fractions of pixels
    this.fx = x
    this.fy = y
  }

  get isVulnerable () {
    return this.state === STATE_LANDED
  }

  start () {
    this.takeOff()
  }

  takeOff () {
    this.setState(STATE_FLYING)
    this.flight = randomInt(this.random, MIN_FLIGHT_STEPS, MAX_FLIGHT_STEPS)
  }

  fly (map) {
    this.angle += (this.random() - 0.5) * 2 * TURN
    let x = this.fx + Math.cos(this.angle) * this.speed
    let y = this.fy + Math.sin(this.angle) * this.speed
    // Back from the edges of the screen
    if (!isInside(map, Math.round(x), Math.round(this.fy), this.width, this.height)) {
      this.angle = Math.PI - this.angle
      x = this.fx
    }
    if (!isInside(map, Math.round(x), Math.round(y), this.width, this.height)) {
      this.angle = -this.angle
      y = this.fy
    }
    this.fx = x
    this.fy = y
    this.x = Math.round(x)
    this.y = Math.round(y)
  }

  act (map) {
    this.spin += this.speed
    switch (this.state) {
      case STATE_FLYING:
        this.speed = Math.min(MAX_SPEED, this.speed + ACCELERATION)
        this.fly(map)
        if (this.steps >= this.flight) {
          this.setState(STATE_LANDING)
        }
        break
      case STATE_LANDING:
        this.speed = Math.max(0, this.speed - ACCELERATION)
        this.fly(map)
        if (this.speed === 0) {
          this.setState(STATE_LANDED)
        }
        break
      case STATE_LANDED:
        if (this.steps >= LANDED_STEPS) {
          this.takeOff()
        }
        break
    }
  }

  // Pushed back from where it landed: the exact position follows
  knockBack (map) {
    super.knockBack(map)
    this.fx = this.x
    this.fy = this.y
  }

  drawBody (context) {
    drawImage(context, resource.getSprite('peahat_move'), Math.floor(this.spin / SPIN_SPEED_STEPS) % 2, this.x, this.y, this.width, this.height)
  }
}

export { Peahat }
