'use strict'

import { ENEMY_SPAWN_CLOUD, TILE_WIDTH, TILE_HEIGHT, SPRITE_TEXT_COLOR_WHITE } from '../constant'
import { spawnEnemies } from './enemy'
import { getPriceLabel } from './cave'
import { restoreSecrets } from './secret'
import resource from '../resource'
import textManager from '../service/text-manager'

class Map {
  constructor (column, line, x, y, width, height, type, tiles, characters, items, extras, enemies = [], enemySpawn = ENEMY_SPAWN_CLOUD, cave = undefined) {
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.offsetX = 0
    this.offsetY = 0
    this.width = width
    this.height = height
    this.type = type
    this.tiles = tiles
    this.characters = characters
    this.items = items
    this.extras = extras
    // What the screen holds ([{ type, count }]) and how they arrive; the enemies there are only
    // while Link is on the screen
    this.enemies = enemies
    this.enemySpawn = enemySpawn
    // What the cave does (CAVE_* in constant.js), undefined for an ordinary screen
    this.cave = cave
    // A cave whose gift was taken is empty from the next visit on
    this.emptied = false
    // Nothing shown yet (potion shop before the letter); set by the game
    this.closed = false
    this.activeEnemies = []
    this.projectiles = []
    // What the dead enemies left, and whether a clock stopped the enemies
    this.drops = []
    this.frozen = false
    // The bomb Link put down, his flames, the rock he pushes, and whether the blue candle burnt here
    this.bombs = []
    this.flames = []
    this.pushes = []
    this.candleUsed = false
    // The flying sword
    this.beams = []

    this.savedItems = []
    this.savedCharacters = []
    this.mapPath = this.getMapPath()
  }

  get character () {
    return this.characters[0]
  }

  getMapPath () {
    const path = new Path2D()
    path.rect(this.x, this.y, this.width, this.height)

    return path
  }

  init () {
    if (this.emptied) {
      this.characters = []
      this.items = []
    }
    for (const character of this.characters) {
      character.init()
    }
    for (const item of this.items) {
      item.init()
      item.label = getPriceLabel(this.cave, item.price)
    }
    for (const extra of this.extras) {
      extra.init()
    }
  }

  reset () {
    for (const character of this.characters) {
      character.reset()
    }
    for (const item of this.items) {
      item.reset()
    }
    for (const extra of this.extras) {
      extra.reset()
    }
    this.clearEnemies()
    restoreSecrets(this)
  }

  spawnEnemies (link, random) {
    this.clearEnemies()
    this.activeEnemies = spawnEnemies(this, link, random)
  }

  clearEnemies () {
    this.activeEnemies = []
    this.projectiles = []
    this.drops = []
    this.frozen = false
    this.bombs = []
    this.flames = []
    this.pushes = []
    this.candleUsed = false
    this.beams = []
  }

  draw (context) {
    context.save()
    context.translate(this.offsetX, this.offsetY)

    for (const tile of this.tilesIterator()) {
      tile.draw(context)
    }
    for (const push of this.pushes) {
      push.draw(context)
    }

    for (const character of this.characters) {
      character.draw(context)
    }

    if (!this.closed) {
      for (const item of this.items) {
        item.draw(context)
      }
      this.drawPriceRow(context)
    }

    for (const extra of this.extras) {
      extra.draw(context)
    }

    // Enemies walking in from outside only show once on the screen
    context.save()
    context.clip(this.mapPath)
    for (const drop of this.drops) {
      drop.draw(context)
    }
    for (const bomb of this.bombs) {
      bomb.draw(context)
    }
    for (const flame of this.flames) {
      flame.draw(context)
    }
    for (const beam of this.beams) {
      beam.draw(context)
    }
    for (const enemy of this.activeEnemies) {
      enemy.draw(context)
    }
    for (const projectile of this.projectiles) {
      projectile.draw(context)
    }
    context.restore()

    context.translate(-this.offsetX, -this.offsetY)
    context.restore()
  }

  // A rupee and "x" in front of the prices, as in the shops of the original
  drawPriceRow (context) {
    if (!this.items.some(item => item.enabled && item.price && item.label)) {
      return
    }
    const y = this.y + 7 * TILE_HEIGHT
    resource.getSprite('item_rupee')?.draw(context, this.x + 2.75 * TILE_WIDTH, y - TILE_HEIGHT / 4, TILE_WIDTH, TILE_HEIGHT)
    textManager.drawLine(context, 'x', SPRITE_TEXT_COLOR_WHITE, this.x + 4 * TILE_WIDTH, y)
  }

  drawBlockingZones (context, color) {
    context.save()
    context.translate(this.offsetX, this.offsetY)
    context.globalAlpha = 0.5
    context.fillStyle = color
    for (const tile of this.tilesIterator()) {
      context.fill(tile.blockPath)
    }
    context.translate(-this.offsetX, -this.offsetY)
    context.restore()
  }

  * tilesIterator () {
    for (let column = 0; column < this.tiles.length; column++) {
      for (let line = 0; line < this.tiles[column].length; line++) {
        yield this.tiles[column][line]
      }
    }
  }

  getTile (column, line) {
    return this.tiles[column] ? this.tiles[column][line] : undefined
  }
}

export { Map }
